"4-Achs-Sätze mit X/Y/Z und A zusammen: Viele Steuerungen rechnen dort Grad wie Millimeter, der Fräser läuft dann am Werkstück zu langsam oder zu schnell. „Umgerechnet“ schreibt den F-Wert so, dass eine solche Steuerung den gewünschten Vorschub an der Schneide fährt. „Zeitreziprok“ schaltet auf G93 und gibt in jedem Satz 1/Zeit an – eindeutig, wenn die Steuerung G93 kennt.":"4-осевые кадры с X/Y/Z и A вместе: многие системы ЧПУ считают там градусы как миллиметры, и фреза идёт по детали слишком медленно или слишком быстро. «Пересчитанная» записывает значение F так, чтобы такая система ЧПУ отрабатывала нужную подачу на режущей кромке. «Обратное время» переключает на G93 и задаёт в каждом кадре 1/время – однозначно, если система ЧПУ поддерживает G93.",
