"Abstand Anfang / Ende macht aus der Lasche eine Teillasche. Weitere geschlossene Profile in der Skizze werden zu Ausschnitten in der Platte. Bohrungen und Fenster in einer Lasche: Mitte entlang der Kante (bei einer gebogenen Kante entlang des Bogens), Mitte ab Ende der Biegung, Größe – sie erscheinen auch in der Abwicklung. Geht eine gebogene Kante ohne Knick in ihre Nachbarkante über und haben beide eine Lasche mit gleichem Biegewinkel, laufen die Laschen ohne Freischnitt ineinander über. „Kontur aus Skizze“ schneidet die geschlossenen Profile einer Skizze aus der Lasche: ihr X läuft entlang der Kante, ihr Y in die Lasche hinein, der Nullpunkt liegt am Kantenanfang auf dem Ende der Biegung (verschiebbar).":"Отступ от начала / конца превращает фланец в частичный. Остальные замкнутые профили эскиза становятся вырезами в пластине. Отверстия и окна во фланце: центр вдоль ребра (у изогнутого ребра – вдоль дуги), центр от конца сгиба, размер – они отображаются и на развёртке. Если изогнутое ребро переходит в соседнее ребро без излома и у обоих есть фланец с одинаковым углом сгиба, фланцы переходят друг в друга без разгрузочного выреза. «Контур из эскиза» вырезает замкнутые профили эскиза из фланца: его ось X идёт вдоль ребра, ось Y – внутрь фланца, нулевая точка лежит в начале ребра на конце сгиба (можно смещать).",
