"Alle Einstellungen, Symbolleisten-Anpassungen und eigenen Tastenkürzel auf die Vorgaben zurücksetzen?\n\nEigene Werkzeugbibliotheken, Materialien und Vorlagen bleiben erhalten.":"Сбросить все параметры, настройки панели инструментов и собственные сочетания клавиш до значений по умолчанию?\n\nСобственные библиотеки инструментов, материалы и шаблоны сохранятся.",
"Alle Flächen des Merkmals wählen: bei einer Bohrung die Wand (und Senkung, Boden), bei einer Tasche Wände und Boden, bei einem Zapfen Mantel und Stirnfläche. Das Merkmal wandert um X/Y/Z; die alte Stelle wird geschlossen. Geht auch bei importierten STEP-Teilen ohne Verlauf. Beim ersten Mal lädt der große Geometriekern (einige Sekunden).":"Выбрать все грани элемента: у отверстия стенку (и цековку, дно), у кармана стенки и дно, у бобышки боковую и торцевую грань. Элемент смещается по X/Y/Z; прежнее место закрывается. Работает и с импортированными деталями STEP без истории. При первом запуске загружается большое геометрическое ядро (несколько секунд).",
"Alle Flächen wählen, die verschwinden sollen (bei einer Tasche Wände und Boden, bei einer Bohrung die Wand, bei einer Verrundung die Rundung). Die Nachbarflächen werden über die Lücke verlängert. Der Schritt rechnet bei Änderungen am Körper mit; beim ersten Mal lädt dafür der große Geometriekern (einige Sekunden).":"Выберите все грани, которые должны исчезнуть (у кармана – стенки и дно, у отверстия – стенку, у скругления – скруглённую грань). Соседние грани продлеваются через зазор. Шаг пересчитывается при изменении тела; при первом запуске для этого загружается полное геометрическое ядро (несколько секунд).",
