"Bei diesem Schnittpunkt bliebe von einer Linie nichts übrig.":"В этой точке пересечения от одной из линий ничего не останется.",
"Bei „Bohrungen“ liegt das Teil auf der Fläche an dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"В режиме «Отверстия» деталь ложится на грань у того конца отверстия, который ближе к точке щелчка. Щёлкайте отверстия по очереди, затем нажмите «Готово».",
"Bei „Bohrungen“ sitzt das Teil bündig in dem Ende der Bohrung, das näher am Klickpunkt liegt. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"В режиме «Отверстия» деталь садится заподлицо в том конце отверстия, который ближе к точке щелчка. Щёлкайте отверстия по очереди, затем нажмите «Готово».",
"Bei „Bohrungen“ sitzt der Kopf auf der Seite der Bohrung, die näher am Klickpunkt liegt; der Schaft zeigt in die Bohrung. Mehrere Bohrungen nacheinander anklicken, dann „Fertig“.":"В режиме «Отверстия» головка располагается со стороны отверстия, ближней к точке щелчка; стержень направлен в отверстие. Щёлкайте отверстия по очереди, затем нажмите «Готово».",
"Beide (in zwei Körper teilen)":"Обе (разделить на два тела)",
