"Beide Netze werden ein Netzkörper. Sie werden nicht verschmolzen: sich durchdringende Teile bleiben, wie sie sind.":"Обе сетки становятся одним сеточным телом. Они не сливаются: пересекающиеся части остаются как есть.",
