"Bohrungen auf einem Lochkreis oder in einem Raster werden als Musterzyklus ausgegeben (Heidenhain CYCL DEF 220/221, Sinumerik HOLES2/CYCLE801). Andere Steuerungen bekommen immer die einzelnen Koordinaten.":"Отверстия на окружности или в сетке выводятся как цикл шаблона (Heidenhain CYCL DEF 220/221, Sinumerik HOLES2/CYCLE801). Другие системы ЧПУ всегда получают отдельные координаты.",
