"Dafür braucht es zwei bewegliche Gelenke (z. B. zwei Drehgelenke für Zahnräder, Dreh- und Schiebegelenk für Zahnstange und Ritzel).":"Нужны два подвижных соединения (например, два вращательных для зубчатых колёс, вращательное и ползун для рейки и шестерни).",
