"Darstellung der Körper":"Отображение тел",
"Darstellung des Werkstücks einstellen: Stil, Kamera, Farbe, Oberfläche, Kanten, Hintergrund":"Настроить отображение заготовки: стиль, камера, цвет, поверхность, рёбра, фон",
