"Drehen: Z vor der Planfläche, auf dem der Revolver schaltet. 0 = Sicherheitsabstand + 100 mm":"Точение: Z перед торцом, на котором поворачивается револьверная головка. 0 = безопасное расстояние + 100 mm",
"Drehen: Zylinder-Interpolation aus":"Точение: цилиндрическая интерполяция выкл.",
"Drehen: Zylinder-Interpolation ein ({cylr} = Radius; leer = Z/C ohne)":"Точение: цилиндрическая интерполяция вкл. ({cylr} = радиус; пусто = Z/C без неё)",
"Drehen: angetriebenes Werkzeug und C-Achse aus":"Точение: приводной инструмент и ось C выкл.",
