"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}) – der Rand reißt dabei meist ein.":"Отбортовка {0}: предварительное отверстие Ø {1} mm расширяется до Ø {2} mm (коэффициент {3}) – край при этом, как правило, надрывается.",
"Durchzug {0}: Vorbohrung Ø {1} mm wird auf Ø {2} mm aufgeweitet (Faktor {3}).":"Отбортовка {0}: предварительное отверстие Ø {1} mm расширяется до Ø {2} mm (коэффициент {3}).",
"Durchzug {0}: liegt {1} mm neben dem Rand (weniger als 2 × Blechdicke) – der Rand beult aus.":"Отбортовка {0}: расположена в {1} mm от края (меньше 2 × толщины листа) – край выпучивается.",
"Durchzug {0}: zu hoch für diese Bohrung (die Vorbohrung bliebe ohne Durchmesser)":"Отбортовка {0}: слишком высокая для этого отверстия (у предварительного отверстия не осталось бы диаметра)",
"Durchzug: der Rand einer runden Bohrung wird zu einem Kragen hochgezogen, etwa als Gewindedurchzug. Der Bohrungsdurchmesser der Skizze ist der fertige Innendurchmesser; im Zuschnitt wird die kleinere Vorbohrung geschnitten.":"Отбортовка: край круглого отверстия вытягивается в бортик, например под резьбу. Диаметр отверстия в эскизе – готовый внутренний диаметр; в заготовке вырезается меньшее предварительное отверстие.",
