"Fläche am bewegten Körper gewählt":"выбрана грань на перемещаемом теле",
"Fläche an ihren Rändern tangential weiterführen":"Продолжить грань по касательной на её краях",
"Fläche anklicken – die Bohrung entsteht mit":"Выберите грань – отверстие создаётся вместе с ней",
"Fläche anklicken, die ersetzt wird.":"Щёлкните грань, которая будет заменена.",
"Fläche anklicken: an jedem Klickpunkt entsteht die Durchgangsbohrung für die Schraube (ISO 273, Reihe mittel) durch alle Teile, die dort aufeinanderliegen – für Senkschrauben mit 90°-Senkung, für Zylinderschrauben auf Wunsch mit Senkbohrung (DIN 974-1, Reihe 1) so tief wie der Kopf. Die Schraube sitzt gleich darin. Bohrung und Schraube lassen sich danach im Verlauf ändern.":"Выберите грань: в каждой выбранной точке создаётся сквозное отверстие под винт (ISO 273, средний ряд) через все лежащие там друг на друге детали – для винтов с потайной головкой с зенковкой 90°, для винтов с цилиндрической головкой по желанию с цековкой (DIN 974-1, ряд 1) на глубину головки. Винт сразу устанавливается в него. Отверстие и винт можно затем изменить на временной шкале.",
"Fläche anpassen":"Подогнать поверхность",
"Fläche anpassen: eine Freiformfläche durch die Punkte einer Punktwolke legen":"Подогнать поверхность: провести поверхность свободной формы через точки облака точек",
"Fläche begradigen":"Выпрямить грань",
"Fläche begradigen: eine Fläche durch eine ruhige Fläche über ihrem Rand ersetzen":"Выпрямить грань: заменить грань гладкой гранью по её границе",
"Fläche cm²":"Площадь cm²",
"Fläche eines Körpers anklicken: ihr Rand kommt als Kontur in die Skizze. Eine Kante anklicken projiziert nur diese Kante (Kreise bleiben Kreise). Projizierte Geometrie ist violett.":"Щёлкните грань тела: её граница попадёт в эскиз как контур. Щелчок по ребру проецирует только это ребро (окружности остаются окружностями). Спроецированная геометрия фиолетовая.",
"Fläche ersetzen":"Заменить грань",
"Fläche ersetzen: eine ebene Fläche auf eine andere Ebene legen – der Körper wächst oder wird gekürzt":"Заменить грань: перенести плоскую грань на другую плоскость – тело увеличивается или сокращается",
"Fläche extrudieren":"Выдавить грань",
"Fläche gewählt – Skizze, Drücken/Ziehen (Q), Extrusion (E), Bohrung (H) oder Schale nimmt sie. Umschalt/Strg + Klick: weitere Flächen.":"Грань выбрана – её использует Эскиз, Тянуть/Толкать (Q), Выдавливание (E), Отверстие (H) или Оболочка. Shift/Ctrl + щелчок: другие грани.",
"Fläche hinter den Fenstern – gilt, wenn oben das Design „Eigenes“ gewählt ist":"Фон за окнами – действует, если выше выбрана тема «Собственная»",
"Fläche löschen":"Удалить грань",
"Fläche löschen: Bohrungen, Taschen, Verrundungen oder Fasen entfernen – die Nachbarflächen schließen die Lücke":"Удалить грань: убрать отверстия, карманы, скругления или фаски – соседние грани закрывают зазор",
"Fläche löschen: OK schließt die Lücke. Den ganzen Körper entfernt Entf, wenn er im Browser gewählt ist.":"Удаление грани: OK закрывает пробел. Тело целиком удаляется клавишей Del, если оно выбрано в браузере.",
"Fläche mit Loch":"Грань с отверстием",
"Fläche oder Kante unter dem Mauszeiger farbig anzeigen":"Выделять цветом грань или ребро под указателем мыши",
"Fläche teilen":"Разделить грань",
"Fläche teilen: Trennkante entlang einer Ebene oder Skizze, der Körper bleibt ein Stück":"Разделить грань: линия разделения по плоскости или эскизу, тело остаётся цельным",
"Fläche versetzen":"Сместить грань",
"Fläche versetzen: ebene Flächen verschieben, Bohrungen und Zapfen im Durchmesser ändern":"Сместить грань: сдвигать плоские грани, изменять диаметр отверстий и цапф",
"Fläche wählen":"Выбрать грань",
"Fläche wählen, die getrimmt wird":"Выбрать обрезаемую поверхность",
"Fläche zum Antasten in Z":"Грань для измерения щупом по Z",
"Fläche {0}":"Грань {0}",
