"Flächen":"Грани",
"Flächen (alle Kanten ringsum)":"Грани (все рёбра по периметру)",
"Flächen (aufeinander legen)":"Грани (совместить друг с другом)",
"Flächen am Körper":"Грани тела",
"Flächen am Teilende (Zweiflach, Vierkant, Sechskant) mit einem angetriebenen Schaftfräser entlang Z. Schlüsselweite = doppelter Abstand der Fläche von der Drehachse. X und C fahren gemeinsam (Polar-Interpolation, Fanuc G12.1); ohne diese Vorlage im Postprozessor werden kurze X/C-Schritte ausgegeben.":"Грани на конце детали (две лыски, квадрат, шестигранник) приводной концевой фрезой вдоль Z. Размер под ключ = удвоенное расстояние грани от оси вращения. X и C движутся совместно (полярная интерполяция, Fanuc G12.1); без этого шаблона в постпроцессоре выводятся короткие шаги X/C.",
"Flächen an einer Ebene oder Skizze auftrennen":"Разделить грани плоскостью или эскизом",
"Flächen an ihren Rändern verbinden – ein geschlossener Verbund wird ein Volumenkörper":"Сшить грани по краям – замкнутый набор становится твёрдым телом",
"Flächen anklicken, die aufgedickt werden (erneut klicken entfernt).":"Щёлкните грани для придания толщины (повторный щелчок снимает выбор).",
"Flächen anklicken, die begradigt werden (erneut klicken entfernt).":"Щёлкните грани для выпрямления (повторный щелчок убирает).",
"Flächen anklicken, die gelöscht werden (erneut klicken entfernt).":"Щёлкните грани для удаления (повторный щелчок убирает).",
"Flächen anklicken, die geneigt werden (erneut klicken entfernt).":"Щёлкните грани для уклона (повторный щелчок снимает выбор).",
"Flächen anklicken, die geteilt werden (erneut klicken entfernt).":"Щёлкните грани для разделения (повторный щелчок убирает).",
"Flächen anklicken, die offen sein sollen.":"Щёлкните грани, которые должны быть открытыми.",
"Flächen anklicken, die versetzt werden (erneut klicken entfernt).":"Щёлкните грани для смещения (повторный щелчок снимает выбор).",
"Flächen eine Wandstärke geben":"Придать граням толщину стенки",
"Flächen im Modell":"Грани в модели",
"Flächen mit Löchern anklicken (erneut klicken entfernt).":"Щёлкните грани с отверстиями (повторный щелчок убирает).",
"Flächen mit gemeinsamen Kanten werden zu einer verbunden. Ist die Hülle rundum geschlossen, entsteht ein Volumenkörper (danach normal weiterbearbeitbar). Lücken größer als die Toleranz bleiben offen.":"Поверхности с общими рёбрами объединяются в одну. Если оболочка полностью замкнута, получается твёрдое тело (далее редактируется как обычно). Зазоры больше допуска остаются открытыми.",
"Flächen sind länger als das Teil":"Лыски длиннее детали",
"Flächen um einen Winkel neigen, damit das Teil aus der Form kommt":"Наклонить грани на угол, чтобы деталь извлекалась из формы",
"Flächen verschieben":"Переместить грани",
