"Flächen wählen, die verschoben werden (bei einer Bohrung die Wand, bei einer Tasche Wände und Boden)":"Выбрать перемещаемые грани (у отверстия стенку, у кармана стенки и дно)",
"Flächen wählen, die verschwinden sollen":"Выберите грани, которые должны исчезнуть",
