"Gelenkursprünge ({0})":"Начала соединений ({0})",
"Gelenkursprünge neu wählen":"Выбрать начала соединения заново",
"Gemeinsame Schnittkanten nur einmal schneiden":"Общие кромки резать только один раз",
"Gemeinsame Schnittkanten: liegen zwei Zuschnitte genau eine Schnittfuge auseinander (beim Schachteln als Abstand die Schnittfuge eintragen), fällt ihre Bahn auf der gemeinsamen Kante zusammen und wird nur einmal geschnitten. Der Anschnitt liegt nie in einem Nachbarteil: ist neben einer Kontur kein freier Abfall, wird auf der Kontur eingestochen. Nach „Vorschau“ zeigt ein Bild je Tafel die Bahn, bevor die Dateien gespeichert werden.":"Общие кромки реза: если две заготовки расположены ровно на ширину реза друг от друга (при раскрое укажите ширину реза как расстояние), их траектории на общей кромке совпадают, и она режется только один раз. Подвод никогда не лежит в соседней детали: если рядом с контуром нет свободного отхода, врезание выполняется на контуре. После «Просмотр» изображение для каждого листа показывает траекторию до сохранения файлов.",
