"Gerade":"Прямая",
"Gerade (radial)":"Прямое (радиальное)",
"Gerade Kante":"Прямое ребро",
"Gerade Linien der Skizze, die zu keinem Profil gehören (auch Hilfslinien). Biegung: die Linie ist die Mitte der Biegezone, die Skizze dort der Zuschnitt – das größte Stück der Platte bleibt liegen, alles jenseits der Linie schwenkt mit seinen Laschen mit. Die Linie gilt über die ganze Platte. Sicke: eine Rippe entlang der Linie, im Querschnitt und an den Enden rund; das Blech behält seine Dicke.":"Прямые линии эскиза, не входящие ни в один профиль (в том числе вспомогательные). Сгиб: линия – середина зоны сгиба, эскиз в этом месте – заготовка; самая большая часть пластины остаётся на месте, всё за линией поворачивается вместе со своими фланцами. Линия действует на всю пластину. Зиг: ребро жёсткости вдоль линии, круглое в сечении и на концах; лист сохраняет свою толщину.",
"Gerade Nuten (Langloch oder Linie mit Nutbreite) gehen als Nutzyklus der Steuerung heraus.":"Прямые пазы (паз или линия с шириной паза) выводятся как цикл паза системы ЧПУ.",
