"Geschafft! Das Teil steht in der Zeitleiste unten – ein Doppelklick auf einen Schritt ändert ihn nachträglich. Weiter geht es mit „Maße als Parameter“ oder „Vom Teil zum NC-Programm“.":"Готово! Деталь находится на временной шкале внизу – двойной щелчок по шагу позволяет изменить его позже. Далее: «Размеры как параметры» или «От детали к УП».",
"Geschlossen":"Замкнутый",
"Geschlossen (Gehrung)":"Закрытые (в ус)",
"Geschlossen: Laschen an zwei Nachbarkanten laufen bis zur Winkelhalbierenden der Ecke und lassen dort den Spalt frei. Die Eckfreistellung sitzt, wo sich die Biegezonen kreuzen – in der Abwicklung und im gebogenen Teil. Auch eine Lasche an einer gebogenen Kante wird an einer echten Ecke auf Gehrung geschnitten (dort ohne Eckfreistellung).":"Закрытые: фланцы на двух соседних рёбрах доходят до биссектрисы угла и оставляют там зазор. Разгрузка угла находится там, где пересекаются зоны гиба, – в развёртке и в согнутой детали. Фланец на криволинейном ребре в реальном углу тоже срезается под углом (там без разгрузки угла).",
"Geschlossene Hohlräume im Inneren des Körpers werden mit Material gefüllt.":"Замкнутые полости внутри тела заполняются материалом.",
"Geschlossene Kette {0}":"Замкнутая цепочка {0}",
"Geschlossene Profile begrenzen den Bereich.":"Замкнутые профили ограничивают область.",
"Geschlossene Profile der aktiven Skizze farbig füllen":"Заливать цветом замкнутые профили активного эскиза",
"Geschlossene Profile werden zu ebenen Flächen – z. B. Deckel und Boden, um Flächen anschließend zu einem Körper zusammenzufügen.":"Замкнутые профили становятся плоскими поверхностями – например, крышка и дно, чтобы затем сшить поверхности в тело.",
"Geschnitten ab X":"Разрез начиная с X",
"Geschwenkte Bearbeitungsebene":"Наклонная плоскость обработки",
"Geschwindigkeit der Animation":"Скорость анимации",
"Geschätzte Bearbeitungszeit (Klick: Details)":"Расчётное время обработки (щелчок: подробности)",
"Gesicherte Vorgaben laden":"Загрузить сохранённые предустановки",
"Gespeichert unter neuem Namen":"Сохранено под новым именем",
"Gespeichert werden Blechdicke {0} mm, Biegeradius innen {1} mm und K-Faktor {2}. Die Regel steht danach bei jedem Blech in der Liste „Blechregel“ – auch in anderen Projekten auf diesem Rechner.":"Будут сохранены толщина листа {0} mm, внутренний радиус гиба {1} mm и K-фактор {2}. После этого правило появится в списке «Правило листового металла» у каждой листовой детали, в том числе в других проектах на этом компьютере.",
"Gespiegelt":"Зеркальный",
"Gestrichelt in der Skizze: Biegelinien (Anfang und Ende jeder Biegezone). Im DXF liegt der Umriss auf Ebene 0, die Biegezonen auf BIEGUNG, die Mittellinie jeder Biegung auf BIEGUNG_AUF (rot) oder BIEGUNG_AB (blau) und Nummer, Winkel und Radius dazu auf BIEGETEXT.":"Штриховые линии в эскизе: линии гиба (начало и конец каждой зоны гиба). В DXF контур лежит на слое 0, зоны гиба – на BIEGUNG, осевая линия каждого гиба – на BIEGUNG_AUF (красная, вверх) или BIEGUNG_AB (синяя, вниз), а его номер, угол и радиус – на BIEGETEXT.",
"Gewebe":"Сетка рёбер",
