"Gewindebohrung im untersten Teil":"Резьбовое отверстие в нижней детали",
"Gewindebohrung im untersten Teil: die Durchgangsbohrung endet, wo das unterste Teil beginnt; dort entsteht das Kernloch mit Gewinde – drei Gewindegänge tiefer, als die Schraube reicht, oder durch das ganze Teil. Liegt nur ein Teil unter dem Punkt, bekommt es das Gewinde von der Fläche an. „Länge passend zur Einschraubtiefe“ nimmt die nächste Länge der Reihe, mit der die Schraube etwa so tief im Gewinde sitzt, wie ihr Gewinde dick ist (Richtwert für Stahl) – aber nie länger, als das Teil dick ist.":"Резьбовое отверстие в нижней детали: сквозное отверстие заканчивается там, где начинается нижняя деталь; в ней создаётся отверстие под резьбу с резьбой – на три витка глубже, чем доходит винт, или на всю деталь. Если под точкой лежит только одна деталь, резьба в ней начинается от грани. «Длина по глубине завинчивания» выбирает ближайшую длину из ряда, при которой винт входит в резьбу примерно на глубину своего диаметра (ориентир для стали), но не длиннее толщины детали.",
"Gewindebohrung {0} – Einschraubtiefe nur {1} mm":"Резьбовое отверстие {0} – глубина ввинчивания всего {1} mm",
