"Gleiche Durchmesser ergeben ein Rohr, verschiedene einen Kegelstumpf. Die Abwicklung wird auf der neutralen Faser gerechnet (Innenfläche + K-Faktor × Blechdicke); beim Runden liegt sie näher an der Blechmitte als beim Abkanten – üblich ist ein K-Faktor von 0,45 bis 0,5. Mit einer Blechregel gelten deren Dicke und K-Faktor. Der Nahtspalt bleibt am größeren Durchmesser offen (0 = stumpf gestoßen, im Körper dann ein Schlitz von 0,01 mm).":"Одинаковые диаметры дают трубу, разные — усечённый конус. Развёртка считается по нейтральному слою (внутренняя поверхность + K-фактор × толщина листа); при вальцовке он лежит ближе к середине листа, чем при листогибе, обычно K-фактор составляет от 0,45 до 0,5. При использовании правила листового металла действуют его толщина и K-фактор. Зазор шва остаётся открытым у большего диаметра (0 = стык встык, в теле тогда получается щель шириной 0,01 mm).",
"Gleiche Länge oder gleichen Radius erzwingen":"Задать равную длину или равный радиус",
"Gleicher Abstand":"Равное расстояние",
"Gleichlauf":"Попутное",
