"Heidenhain: an der Steuerung die Datenübertragung über Ethernet freigeben (wie für TNCremo, LSV2, Port 19000); Standardordner TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: Port 21, Ordner z. B. /_N_WKS_DIR oder /NC. Netzwerkordner: Pfad wie \\\\MASCHINE\\NC oder Z:\\NC. DNC: Wandler als TCP-Server (raw), meist Port 4001; an der Steuerung „Abarbeiten extern“, DNC oder TAPE starten.":"Heidenhain: на системе ЧПУ разрешить передачу данных по Ethernet (как для TNCremo, LSV2, порт 19000); папка по умолчанию TNC 640 TNC:\\nc_prog\\, iTNC 530 TNC:\\. FTP: порт 21, папка, например, /_N_WKS_DIR или /NC. Сетевая папка: путь вида \\\\MASCHINE\\NC или Z:\\NC. DNC: преобразователь как TCP-сервер (raw), обычно порт 4001; на системе ЧПУ запустить «Внешняя отработка», DNC или TAPE.",
