"Im Programm: die Designs liegen im Speicher des Programms auf diesem Computer. Ordner: jedes Design liegt zusätzlich als .ofab-Datei in einem Ordner Ihrer Wahl, z. B. auf einem Netzlaufwerk oder in einem synchronisierten Ordner. Die gespeicherten Versionen bleiben im Programm.":"В программе: проекты хранятся в памяти программы на этом компьютере. Папка: каждый проект дополнительно сохраняется как файл .ofab в выбранной вами папке, например на сетевом диске или в синхронизируемой папке. Сохранённые версии остаются в программе.",
"Im Setup gewählt, bestimmt die Maschine Postprozessor, Eilgang (Laufzeit) und die Grenzwert-Prüfungen.":"Выбранный в установе станок определяет постпроцессор, ускоренное перемещение (время работы) и проверки предельных значений.",
"Im Spiegelbild läuft das Werkzeug andersherum: aus Gleichlauf wird dort Gegenlauf. Die Radiuskorrektur der Steuerung wechselt die Seite mit.":"В зеркальном отражении инструмент идёт в обратную сторону: попутное фрезерование там становится встречным. Коррекция на радиус в системе ЧПУ тоже меняет сторону.",
