"Importierte Körper sind ohne Konstruktionshistorie, lassen sich aber weiterbearbeiten (Verrundung, Fase, Ausschneiden …) und für CAM verwenden. Mit „Y-Achse oben“ werden Modelle aus Programmen mit Y nach oben richtig hingestellt.":"Импортированные тела не имеют истории построения, но их можно дорабатывать (скругление, фаска, вырез …) и использовать для CAM. «Ось Y вверх» правильно ставит модели из программ, где Y направлена вверх.",
