"Kante {0}: Lasche an einer gebogenen Kante – ihr Rand wird beim Umformen um {1} % gestreckt (Rissgefahr); der Zuschnitt ist dort eine Näherung.":"Ребро {0}: фланец на изогнутом ребре – его кромка при формовке растягивается на {1} % (риск образования трещин); заготовка здесь приближённая.",
