"Kante {0}: die Lasche kreuzt eine Biegelinie – mit „Abstand Anfang / Ende“ vor der Biegung enden lassen":"Ребро {0}: фланец пересекает линию сгиба – завершите его перед сгибом с помощью «Отступ от начала / конца»",
