"Kante {0}: ein Ausschnitt in der Lasche liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Ребро {0}: вырез во фланце расположен в {1} mm от сгиба (меньше 2 × толщины листа) – при гибке он деформируется.",
"Kante {0}: ein Ausschnitt liegt {1} mm neben der Biegung (weniger als 2 × Blechdicke) – er verzieht sich beim Biegen.":"Ребро {0}: вырез расположен в {1} mm от сгиба (меньше 2 × толщины листа) – при гибке он деформируется.",
