"Kante {0}{1}: Lasche {2} mm ist kürzer als 2 × Blechdicke – auf der Abkantpresse kaum zu biegen.":"Ребро {0}{1}: фланец {2} mm короче 2 × толщины листа – на листогибочном прессе его почти невозможно согнуть.",
