"Kante {0}{1}: geschlossener Saum (Innenradius {2} mm) – wird in zwei Hüben gebogen und zugedrückt; harte Werkstoffe reißen dabei an der Außenseite.":"Ребро {0}{1}: закрытая отбортовка (внутренний радиус {2} mm) — гнётся в два хода и прижимается; твёрдые материалы при этом трескаются с наружной стороны.",
