"Kappe schieben = verschieben, drücken/ziehen = zoomen, kippen und drehen = Modell drehen. In Skizzen nur Verschieben und Zoomen. SpaceMouse Pro/Enterprise: T, F, R = Ansicht oben, vorne, rechts. Falls nichts passiert: 3Dconnexion-Treiber kurz beenden und neu verbinden.":"Сдвиг колпачка = панорамирование, нажатие/вытягивание = масштаб, наклон и поворот = вращение модели. В эскизах только панорамирование и масштаб. SpaceMouse Pro/Enterprise: T, F, R = вид сверху, спереди, справа. Если ничего не происходит: ненадолго закройте драйвер 3Dconnexion и подключитесь снова.",
