"Kieme: die Linie ist ein Schlitz, das Blech daneben wird zu einer Haube aufgestellt, die an beiden Enden des Schlitzes in die Platte ausläuft (Lüftungsschlitz). Im Zuschnitt ist der Schlitz ein Schnitt.":"Жалюзи: линия является прорезью, лист рядом с ней отгибается в виде козырька, который на обоих концах прорези переходит в пластину (вентиляционная прорезь). В заготовке прорезь – это разрез.",
