"Kugel-, Schaft-, Torus- oder Konusfräser. Ein Kugelfräser behält seine Bahn; andere Fräser werden geneigt und entlang ihrer Achse verschoben, bis sie am Teil anliegen, ohne es zu verletzen. Höchstens die größte Neigung; wo Schaft oder Halter das Teil berühren würden, richtet sich das Werkzeug auf. Ausgabe als Werkzeugvektor (Heidenhain, Sinumerik, Fanuc), sonst als 3-Achs-Bahn.":"Шаровая, цилиндрическая, торообразная или коническая концевая фреза. Шаровая фреза сохраняет свою траекторию; остальные фрезы наклоняются и смещаются вдоль оси, пока не прилегут к детали без её повреждения. Не более максимального наклона; где хвостовик или оправка коснулись бы детали, инструмент выпрямляется. Вывод в виде вектора инструмента (Heidenhain, Sinumerik, Fanuc), иначе в виде 3-осевой траектории.",
