"Lasche an Lasche: Winkel + biegt in dieselbe Richtung weiter (U-Profil, Falz mit 180°), − in die Gegenrichtung (Z-Stufe, Hutprofil). Saum: der Rand der Lasche wird um 180° auf sich selbst zurückgelegt – offen mit einem Spalt von einer Blechdicke, geschlossen flach zugedrückt; mit − 180° liegt er auf der anderen Seite. Das Feld R ist der Innenradius nur dieser Biegung (leer = wie beim Blech). Für einen Saum direkt an der Plattenkante die Lasche selbst auf 180° stellen. Kröpfung: zwei Biegungen gegeneinander (− 45° und + 45°) – der Rand läuft parallel versetzt weiter; Versatz über die Länge des schrägen Stücks und die Winkel.":"Фланец на фланце: угол + продолжает гиб в том же направлении (U-профиль, фальц на 180°), − в обратном (Z-ступень, омега-профиль). Отбортовка: кромка фланца загибается на 180° на саму себя — открытая с зазором в одну толщину листа, закрытая плотно прижатая; при − 180° она ложится на другую сторону. Поле R — внутренний радиус только этого гиба (пусто = как для листа). Для отбортовки прямо на кромке пластины задайте для самого фланца 180°. Отгиб-смещение: два встречных гиба (− 45° и + 45°) — кромка идёт дальше параллельно со смещением; смещение определяется длиной наклонного участка и углами.",
"Lasche {0}":"Фланец {0}",
"Laschen, die über eine Biegelinie laufen, sind dort geteilt und freigestellt.":"Фланцы, пересекающие линию сгиба, в этом месте разделяются и получают разгрузочные вырезы.",
