"Macht ein geschlossenes Netz hohl: eine Innenwand im Abstand der Wandstärke kommt dazu – spart Material und Druckzeit. Stellen, die dünner sind als zwei Wandstärken, überschneiden sich danach; für Harzdruck ein Ablaufloch mit „Boolesch“ abziehen.":"Делает замкнутую сетку полой: добавляется внутренняя стенка на расстоянии толщины стенки – экономит материал и время печати. Места тоньше двух толщин стенки после этого пересекаются; для печати смолой вычтите дренажное отверстие командой «Булева операция».",
