"Material im Setup unter „Rohteil → Rohteilmaterial“ wählen. Die Dichte ergibt das Rohteilgewicht, Vc ist ein Richtwert für Hartmetall; die Farbe zeigt die Simulation.":"Материал выбирается в установе в разделе «Заготовка → Материал заготовки». Плотность даёт массу заготовки, Vc – ориентировочное значение для твёрдого сплава; цвет показывает симуляция.",
