"Mehrere Zustellungen und Leerdurchgang gibt es nur als Bahn":"Несколько подач на глубину и холостой проход возможны только как траектория",
"Mehrere aneinanderhängende Kanten zählen als eine Strecke: Der Radius läuft vom Anfang der Kette bis zu ihrem Ende, Stützpunkte gelten in % der ganzen Kettenlänge. Das rechnet der große Geometriekern.":"Несколько соединённых рёбер считаются одним участком: радиус меняется от начала цепочки до её конца, опорные точки задаются в % от всей длины цепочки. Это рассчитывает полное геометрическое ядро.",
"Mehrfachaufspannung":"Многоместная установка",
"Mehrfachaufspannung: Nullpunkt von Teil {0} gibt es an dieser Steuerung nicht – nur ein Teil ausgegeben":"Многоместная установка: в этой системе ЧПУ нет нулевой точки для детали {0} – выведена только одна деталь",
"Mehrfachaufspannung: Nullpunktverschiebung gibt es in diesem Postprozessor nicht – „Eigener Nullpunkt je Teil“ wählen; nur ein Teil ausgegeben":"Многоместная установка: в этом постпроцессоре нет смещения нулевой точки – выберите «Своя нулевая точка для каждой детали»; выведена только одна деталь",
