"Meldet Bahnen, die tiefer schneiden als das Modell an dieser Stelle (Schaft-, Plan-, Kugel- und Torusfräser, Fasenfräser und Bohrer mit ihrem Kegel; 3-Achs-Bewegungen). Ein Schnitt, der nicht im Modell steht – Gravur, Eckenfreistich, Tasche nur aus einer Skizze – wird ebenfalls gemeldet.":"Сообщает о траекториях, которые режут глубже модели в этом месте (концевые, торцевые, сферические и тороидальные фрезы, фасочные фрезы и сверла с их конусом; 3-осевые перемещения). Рез, которого нет в модели — гравировка, поднутрение углов, карман только из эскиза — также отмечается.",
