"Mit Stützpunkten läuft der Radius durch die angegebenen Werte (Lage in % der Kantenlänge). Das rechnet der große Geometriekern; beim ersten Mal lädt er einige Sekunden.":"С опорными точками радиус проходит через заданные значения (положение в % от длины ребра). Это рассчитывает полное геометрическое ядро; при первом запуске оно загружается несколько секунд.",
