"Mit dem 3D-Taster kann nicht zerspant werden":"3D-щупом нельзя резать",
"Mit dem Fertigteil vergleichen: grün = auf Maß, blau = Restmaterial, rot = zu tief":"Сравнить с готовой деталью: зелёный = в размер, синий = остаточный материал, красный = слишком глубоко",
"Mit dem Reiter „{0}“ vergleichen?\n\nAbbrechen = eine Datei wählen":"Сравнить с вкладкой «{0}»?\n\nОтмена = выбрать файл",
"Mit dem Werkzeug-Taster (TT) direkt nach dem TOOL CALL: Q340=1 prüft gegen die Werkzeugtabelle, schreibt die Abweichung als DL/DR und sperrt das Werkzeug bei überschrittener Verschleiß- oder Bruchtoleranz":"Щупом для инструмента (TT) сразу после TOOL CALL: Q340=1 проверяет по таблице инструментов, записывает отклонение как DL/DR и блокирует инструмент при превышении допуска на износ или поломку",
"Mit der Maus neben eine Kontur fahren (die Seite bestimmt die Richtung) · Esc beendet":"Подвести мышь к контуру (сторона задаёт направление) · Esc – завершить",
"Mit der Maus zeigen":"Указать мышью",
"Mit diesem Werkzeug kann nicht gefräst werden":"Этим инструментом нельзя фрезеровать",
"Mit einem Gewindebohrer nur Zyklus „Gewindebohren“ – ein Bohrzyklus würde ihn abbrechen":"С метчиком только цикл «Нарезание резьбы метчиком» – цикл сверления его сломает",
"Mit gedrückter Maustaste ziehen. Doppelklick setzt die Leiste zurück an ihren Platz":"Перетаскивайте с зажатой кнопкой мыши. Двойной щелчок возвращает панель на место",
"Mit mehreren Zustellungen wird die Gewindetiefe in Schritten gefräst, die jeweils etwa gleich viel abnehmen – schont kleine Gewindefräser und harte Werkstoffe. Der Leerdurchgang fährt die letzte Bahn noch einmal ohne Zustellung.":"При нескольких проходах глубина резьбы фрезеруется ступенями, каждая из которых снимает примерно одинаковый слой – это щадит малые резьбовые фрезы и твёрдые материалы. Выхаживающий проход повторяет последнюю траекторию ещё раз без подачи на глубину.",
"Mit „Bohrzyklen“ im NC-Programm werden Steuerungszyklen ausgegeben (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), sonst ausgeschriebene Bewegungen.":"При включённых «Циклах сверления» в управляющей программе выводятся циклы системы ЧПУ (G81–G86, Heidenhain CYCL 200–207, Sinumerik CYCLE81–85), иначе – развёрнутые перемещения.",
"Mit „Original behalten“ werden Original und Spiegelbild ein Netz; Punkte auf der Spiegelebene werden verbunden – aus einer offenen Hälfte wird so ein geschlossenes Teil.":"С параметром «Сохранить оригинал» оригинал и его зеркальное отражение становятся одной сеткой; точки на плоскости симметрии соединяются – так открытая половина превращается в замкнутую деталь.",
