"Niedrig (0,05 mm)":"Низкое (0,05 mm)",
"Noch kein Dreh-Setup: „Neues Setup“ → Operationstyp „Drehen“ wählen.":"Токарного установа ещё нет: «Новый установ» → выбрать тип операции «Точение».",
"Noch kein Fräs-Setup vorhanden.":"Фрезерного установа ещё нет.",
"Noch kein Körper gewählt – bis dahin gilt die relative Quadergröße.":"Тело ещё не выбрано – пока действует относительный размер параллелепипеда.",
"Noch kein Körper vorhanden – erst in KONSTRUKTION modellieren.":"Тела ещё нет – сначала смоделировать в ПРОЕКТИРОВАНИИ.",
"Noch kein Profil gewählt – Bereiche der Skizze anklicken.":"Профиль ещё не выбран – щёлкните области эскиза.",
"Noch kein Prüfpunkt gesichert.":"Контрольная точка ещё не сохранена.",
"Noch kein Skript – eine .py-Datei oder einen Ordner laden.":"Скриптов пока нет – загрузите файл .py или папку.",
"Noch kein Wiederherstellungspunkt – der erste entsteht, sobald sich der Entwurf ändert und die eingestellte Zeit vergangen ist.":"Точек восстановления пока нет – первая появится, когда проект изменится и пройдёт заданное время.",
"Noch kein Zusatzmodul – einen Ordner mit Zusatzmodul laden.":"Дополнений пока нет – загрузите папку с дополнением.",
"Noch keine Designs gespeichert.":"Сохранённых проектов пока нет.",
"Noch keine Designs – links mit „Neues Design“ oder einem Beispiel beginnen.":"Проектов пока нет – начните слева с «Новый проект» или с примера.",
"Noch keine Kommentare. Mit + Notizen zum Design festhalten.":"Комментариев пока нет. Кнопкой + добавьте заметки к проекту.",
"Noch keine Konfiguration – erst Varianten anlegen oder eine Tabelle einlesen.":"Конфигурации ещё нет – сначала создать варианты или импортировать таблицу.",
"Noch keine Konfiguration.":"Конфигурации ещё нет.",
"Noch keine Konfiguration. „Konfigurieren“ speichert die jetzigen Parameterwerte als Variante.":"Конфигураций пока нет. «Настроить» сохраняет текущие значения параметров как вариант.",
"Noch keine Operation":"Операций пока нет",
"Noch keine Parameter angelegt.":"Параметры ещё не созданы.",
"Noch keine Skizze vorhanden – zuerst „Skizze“ wählen.":"Эскиза пока нет – сначала выберите «Эскиз».",
"Noch keine Vorlagen. Eine Vorlage speichert Strategien mit allen Einstellungen (Werkzeug, Schnittdaten, Höhen, Durchgänge, Verknüpfung) zum Wiederverwenden in anderen Setups und Designs.":"Шаблонов пока нет. Шаблон сохраняет стратегии со всеми параметрами (инструмент, режимы резания, высоты, проходы, переходы) для повторного использования в других установах и проектах.",
"Noch keine Werkzeuge im Dokument.":"В документе пока нет инструментов.",
"Noch keine benannte Ansicht gespeichert.":"Именованных видов пока не сохранено.",
"Noch keine. Geometrie wählen und oben unter ABHÄNGIGKEITEN ein Werkzeug anklicken.":"Пока нет. Выбрать геометрию и щёлкнуть инструмент вверху в разделе ЗАВИСИМОСТИ.",
