"Oben auf FERTIGUNG wechseln für CAM.":"Для CAM перейти вверху в ПРОИЗВОДСТВО.",
"Oben links den Arbeitsbereich „Fertigung“ wählen.":"Выбрать слева вверху рабочее пространство «Производство».",
"Oben, Vorne, Rechts":"Сверху, Спереди, Справа",
"Obere Höhe":"Верхняя высота",
"Oberer Ø":"Верхний Ø",
"Oberes Abmaß":"Верхнее отклонение",
"Oberfläche":"Площадь поверхности",
"Oberfläche Z":"Поверхность Z",
"Oberflächenzeichen hinzufügen":"Добавить знак шероховатости",
"Oberflächenzeichen und Bezüge bitte in der Vorder-, Drauf- oder Seitenansicht setzen.":"Знаки шероховатости и базы проставляйте на виде спереди, сверху или сбоку.",
"Oberflächenzeichen: eine Kante im Blatt anklicken":"Знак шероховатости: щёлкните ребро на листе",
"Oberhalb / Plusseite":"Выше / сторона плюс",
"Oberkante auf der Linie":"Верхняя кромка на линии",
"Oberseite des Rechtecks bzw. Taschenboden":"Верх прямоугольника или дно кармана",
"Oberseite des Rohteils eben fräsen":"Фрезеровать верх заготовки в плоскость (торцевание)",
"Objekte":"Объекты",
"Objekte anklicken (erneut anklicken nimmt sie wieder heraus).":"Щёлкните объекты (повторный щелчок снимает выбор).",
"Oder Skizze":"Или эскиз",
"Offen (Laschen gekürzt)":"Открытые (фланцы укорочены)",
"Offene Flächen":"Открытые грани",
"Offene Kanten werden rot angezeigt. „Reparieren“ schließt Löcher.":"Открытые рёбра показаны красным. «Исправить» закрывает отверстия.",
"Offene Linie in einer Skizze wählen":"Выбрать незамкнутую линию в эскизе",
"Offene Stirnfläche eines Rohrs oder Profils anklicken.":"Щёлкните открытую торцевую грань трубы или профиля.",
"Offene oder geschlossene Kurven werden senkrecht zur Skizze gezogen – es entsteht eine Fläche (Wand ohne Dicke). Mit „Aufdicken“ oder „Zusammenfügen“ wird daraus ein Volumen.":"Незамкнутые или замкнутые кривые вытягиваются перпендикулярно эскизу – получается поверхность (стенка без толщины). «Придать толщину» или «Сшить» превращает её в твёрдое тело.",
"Offene oder geschlossene Kurven werden um die Achse gedreht – es entsteht eine Fläche, kein Volumen.":"Незамкнутые или замкнутые кривые вращаются вокруг оси – получается поверхность, а не твёрдое тело.",
"Ohne Mutter":"Без гайки",
"Ohne eigene Taste gilt der Standard „{0}“.":"Без своей клавиши действует стандартная «{0}».",
"Ohne „Modelliert“ wird das Gewinde nur dargestellt (schnell). Modelliert wird die Gewindeform wirklich ausgeschnitten, z. B. für 3D-Druck. Bohrung für M8 = Ø6,8.":"Без «Смоделированная» резьба только изображается (быстро). При моделировании профиль резьбы действительно вырезается, например для 3D-печати. Отверстие под M8 = Ø6,8.",
"Okuma OSP Drehen":"Okuma OSP, точение",
"Okuma OSP-M Fräsen":"Okuma OSP-M, фрезерование",
"Okuma OSP: G28/G53 fahren dort nicht auf Maschinenkoordinaten (G53 hebt die Werkzeuglängenkorrektur auf) – Rückzug auf Sicherheitshöhe, keine XY-Referenzfahrt ausgegeben":"Okuma OSP: G28/G53 там не перемещают в координаты станка (G53 отменяет коррекцию на длину инструмента) – отвод на безопасную высоту, выход в ноль XY не выводится",
"Okuma OSP: keine Glättungsfunktion ausgegeben (G5.1 ist Fanuc) – Hi-Cut/Super-NURBS an der Maschine einstellen":"Okuma OSP: функция сглаживания не выводится (G5.1 – это Fanuc) – настройте Hi-Cut/Super-NURBS на станке",
"Okuma: Korrektur+Werkzeug+Schneide (z. B. 010101)":"Okuma: корректор+инструмент+кромка (напр. 010101)",
"OpenCascade: rechnet alle Schritte. Rust-Kern (truck, experimentell): rechnet Designs aus Grundkörpern, Extrusion, Rotation, Bohrung, Muster, Spiegeln, Verschieben, Skalieren und Kombinieren selbst. Enthält ein Design einen anderen Schritt (z. B. Verrundung, Fase, Kegelsenkung) oder scheitert der Rust-Kern an einem Schritt, rechnet OpenCascade dieses Design von selbst – es funktioniert also mit beiden Einstellungen alles. Welcher Kern gerechnet hat, steht rechts unter MODELL.":"OpenCascade: рассчитывает все шаги. Ядро Rust (truck, экспериментальное): само рассчитывает проекты из примитивов, выдавливания, вращения, отверстия, массива, зеркала, перемещения, масштабирования и объединения. Если в проекте есть другой шаг (напр. скругление, фаска, коническая зенковка) или ядро Rust не справляется с шагом, этот проект автоматически рассчитывает OpenCascade – то есть при обеих настройках всё работает. Какое ядро выполнило расчёт, указано справа под МОДЕЛЬ.",
"Operation":"Операция",
