"Punkte, Linien oder Kreise anklicken (Umschalt = mehrere), dann Abhängigkeit oder Bemaßung wählen. Punkte/Linien ziehen zum Verformen. Entf löscht.":"Щёлкнуть точки, линии или окружности (Shift = несколько), затем выбрать зависимость или размер. Перетаскивать точки/линии для изменения формы. Del удаляет.",
