"Schraubstock: die Backen greifen quer zur X-Achse des Setups (an Y-min und Y-max des Rohteils); 0 = Größe und Spanntiefe passend wählen. Die Spannmittel werden einfache Körper am Ende der Zeitleiste und hier als Spannmittel eingetragen: Halter- und Kollisionsprüfung, Sicherheitsabstände und Einrichteblatt berücksichtigen sie.":"Тиски: губки зажимают поперёк оси X установа (по Y-min и Y-max заготовки); 0 = подобрать размер и глубину зажима автоматически. Приспособления становятся простыми телами в конце временной шкалы и вносятся сюда как приспособления: их учитывают проверка державки и столкновений, безопасные расстояния и карта наладки.",
