"Schruppt die Bohrung von der Vorbohrung nach außen (0,2 mm Schlichtaufmaß) und schlichtet sie dann bis zum Grund. Die Bohrstange muss in die Vorbohrung passen.":"Черновая расточка отверстия от предварительного отверстия наружу (чистовой припуск 0,2 мм), затем чистовая до дна. Расточная оправка должна входить в предварительное отверстие.",
