"Sätze mit X/Y/Z und A zusammen: Der Vorschub steht in mm/min im Programm, viele Steuerungen rechnen dort aber Grad wie Millimeter – Einstellung „Vorschub mit Drehachse“ des Postprozessors auf „umgerechnet“ oder „zeitreziprok (G93)“ stellen":"Кадры с X/Y/Z и A вместе: подача в программе задана в mm/min, но многие системы ЧПУ считают там градусы как миллиметры – установить настройку постпроцессора «Подача с осью вращения» на «пересчитанная» или «обратное время (G93)»",
