"Tasche Planfläche (C-Achse)":"Карман на торце (ось C)",
"Tasche auf dem Umfang aus den geschlossenen Konturen einer Skizze, die längs zur Drehachse liegt (innere Konturen bleiben als Inseln stehen). Die Skizze wird auf den Durchmesser gewickelt; ein angetriebener Schaftfräser, der zur Achse zeigt, räumt von innen nach außen (Z und C fahren gemeinsam; Fanuc: Zylinder-Interpolation G7.1). Der Fräser taucht auf einer Rampe entlang des innersten Rings ein.":"Карман на цилиндрической поверхности по замкнутым контурам эскиза, расположенного вдоль оси вращения (внутренние контуры остаются островками). Эскиз наматывается на диаметр; приводная концевая фреза, направленная к оси, выбирает материал изнутри наружу (Z и C перемещаются совместно; Fanuc: цилиндрическая интерполяция G7.1). Фреза врезается по наклонной траектории вдоль самого внутреннего кольца.",
"Tasche bis zum Boden ausräumen":"Обработать карман до дна",
"Tasche gespiegelt":"Зеркальный карман",
"Tasche in den Mantel fräsen, die C-Achse dreht mit":"Фрезеровать карман в цилиндрической поверхности, ось C вращается синхронно",
"Tasche in der Planfläche aus den geschlossenen Konturen einer Skizze (innere Konturen bleiben als Inseln stehen), mit einem angetriebenen Schaftfräser entlang Z. Geräumt wird von innen nach außen; der Fräser taucht auf einer Rampe entlang der innersten Bahn ein und bleibt innerhalb einer Ebene unten. X und C fahren gemeinsam (Fanuc: Polar-Interpolation G12.1). Tiefe ab Planfläche.":"Карман в торце по замкнутым контурам эскиза (внутренние контуры остаются островами), приводной концевой фрезой вдоль Z. Выборка идёт изнутри наружу; фреза врезается наклонно вдоль самого внутреннего прохода и в пределах одного уровня остаётся внизу. X и C движутся совместно (Fanuc: полярная интерполяция G12.1). Глубина от торца.",
"Tasche in die Stirnfläche fräsen":"Фрезеровать карман в торце",
