"Teil 1 liegt normalerweise auf dem Nullpunkt (0, 0, 0). Die anderen werden mit einer Nullpunktverschiebung angefahren (Heidenhain Zyklus 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Vor jedem Wechsel geht das Werkzeug auf die sichere Höhe.":"Деталь 1 обычно находится в нулевой точке (0, 0, 0). К остальным выход выполняется со смещением нулевой точки (Heidenhain цикл 7, Fanuc/LinuxCNC G52, Sinumerik TRANS). Перед каждым переходом инструмент отводится на безопасную высоту.",
