"Teilkreis Ø {0} · Kopfkreis Ø {1} · Fußkreis Ø {2} · Steigung {3} mm · Steigungswinkel {4}°":"Делительная окружность Ø {0} · окружность вершин Ø {1} · окружность впадин Ø {2} · ход {3} мм · угол подъёма {4}°",
