"Vernetzung fehlgeschlagen:":"Ошибка построения сетки:",
"Verrechnet zwei geschlossene Netze wirklich miteinander: innen liegende Flächen verschwinden, die Schnittkanten werden neu vernetzt. Gerechnet wird nur dort, wo sich die beiden Netze begegnen können – ein großes Netz mit einem kleinen Eingriff geht deshalb schnell. Überlappen zwei große Netze ganz, vorher „Reduzieren“.":"Выполняет настоящую операцию над двумя замкнутыми сетками: внутренние грани исчезают, рёбра пересечения строятся заново. Расчёт ведётся только там, где две сетки могут пересекаться, поэтому большая сетка с небольшим вмешательством обрабатывается быстро. Если две большие сетки перекрываются полностью, сначала выполните «Упростить».",
