"Verschiebt jede Fläche um den Abstand nach außen (negativ: nach innen) – für Spiel, Aufmaß oder ein Negativ. Kanten und Ecken bleiben scharf; sehr feine Stellen können sich beim Schrumpfen überschneiden.":"Смещает каждую грань наружу на заданное расстояние (отрицательное значение: внутрь) – для зазора, припуска или негатива. Рёбра и углы остаются острыми; очень мелкие участки при сжатии могут пересекаться.",
