"Verschleiß":"Износ",
"Verschraubung: Scheiben und Mutter kommen mit der Schraube in einem Zug an jede angeklickte Bohrung. Die Klemmdicke ist die Länge der Bohrung – durch mehrere Teile hindurch, wenn ihre Bohrungen fluchten und aneinanderstoßen. Mit Mutter wird die kürzeste Vorzugslänge vorgeschlagen, bei der die Schraube zwei Gewindegänge aus der Mutter ragt.":"Болтовое соединение: шайбы и гайка устанавливаются вместе с винтом за одно действие в каждое выбранное отверстие. Толщина зажимаемого пакета – это длина отверстия, через несколько деталей, если их отверстия соосны и примыкают друг к другу. С гайкой предлагается наименьшая предпочтительная длина, при которой винт выступает из гайки на два витка резьбы.",
"Verschraubung: {0} – Klemmdicke {1} mm":"Болтовое соединение: {0} – толщина пакета {1} mm",
"Verschraubung: {0} – die Schraube ist für die Klemmdicke {1} mm zu kurz (nötig: {2} mm)":"Болтовое соединение: {0} – винт слишком короткий для толщины пакета {1} mm (нужно: {2} mm)",
"Verschraubung: {0} – {1}; die Schraube ist für die Klemmdicke {2} mm zu kurz (nötig: {3} mm)":"Болтовое соединение: {0} – {1}; винт слишком короткий для толщины пакета {2} mm (нужно: {3} mm)",
