"Wickelt die Skizzenkurven auf den Zylinder: X bleibt X, der Abstand quer zur Achse wird zum Bogen auf dem Abwicklungs-Ø (Drehung A). Die Skizze muss parallel zur A-Achse liegen, z. B. auf einer Tangentialebene. Gefräst wird in fester Tiefe unter der Teiloberfläche – für Gravuren, Schriften und Nuten rund um das Teil.":"Наматывает кривые эскиза на цилиндр: X остаётся X, расстояние поперёк оси становится дугой на Ø намотки (поворот A). Эскиз должен быть параллелен оси A, напр. на касательной плоскости. Фрезерование идёт на постоянной глубине под поверхностью детали – для гравировок, надписей и пазов вокруг детали.",
"Wie 3D-Kontur, aber das Werkzeug fährt ohne Absätze kontinuierlich nach unten – keine Eintauchmarken an steilen Wänden.":"Как 3D-контур, но инструмент опускается непрерывно, без ступеней – без следов врезания на крутых стенках.",
"Wie Einfahrt":"Как подвод",
"Wie ausgewählt":"Как выбрано",
"Wie die Ansicht":"Как в виде",
"Wie die Ansicht (alle Dreiecke)":"Как на виде (все треугольники)",
"Wie fein Körper für STL, 3MF und den Slicer in Dreiecke zerlegt werden: Abweichung von der wahren Fläche als Anteil der Körpergröße. Netze bleiben, wie sie sind.":"Насколько мелко тела разбиваются на треугольники для STL, 3MF и слайсера: отклонение от истинной поверхности как доля размера тела. Сетки остаются как есть.",
"Wie fein Zylinder, Kugeln und Rundungen in der Ansicht aus Dreiecken bestehen. Feiner sieht runder aus, rechnet bei großen Modellen aber länger. Der Export hat eine eigene Einstellung (3D-Druck).":"Насколько мелко цилиндры, сферы и скругления в виде разбиты на треугольники. Чем мельче, тем круглее выглядит, но на больших моделях расчёт занимает дольше. У экспорта есть собственная настройка (3D-печать).",
"Wie im System":"Как в системе",
