"Zahnform nach Tredgold (Ersatz-Stirnrad auf dem Rückenkegel), gerade Zähne. Das große Ende liegt in der Grundebene, die Zähne laufen zur Kegelspitze. Für Darstellung, 3D-Druck und Fräsen aus dem Vollen; geschliffene Kegelräder brauchen die Daten des Herstellers.":"Профиль зуба по Tredgold (эквивалентное цилиндрическое колесо на дополнительном конусе), прямые зубья. Большой торец лежит в базовой плоскости, зубья направлены к вершине конуса. Для изображения, 3D-печати и фрезерования из цельной заготовки; шлифованным коническим колёсам нужны данные изготовителя.",
