"Zungen stehen am freien Ende der Lasche über und kommen in den Zuschnitt. „Schlitze als Skizze“ legt die passenden Schlitze dort an, wo die Zungen stehen – je Ebene eine Skizze, jeder Schlitz ringsum um das Spiel größer als die Zunge. In dieser Skizze den Umriss des Gegenstücks zeichnen und daraus ein Blech oder eine Extrusion machen: die Schlitze werden Ausschnitte. Das Gegenstück liegt auf den Laschenenden auf; die Zungenlänge ist üblich gleich seiner Dicke.":"Шипы выступают на свободном конце фланца и входят в развёртку заготовки. «Пазы в виде эскиза» создаёт подходящие пазы там, где находятся шипы, — по одному эскизу на плоскость, каждый паз со всех сторон больше шипа на величину зазора. В этом эскизе начертите контур ответной детали и создайте из него лист или выдавливание: пазы станут вырезами. Ответная деталь опирается на концы фланцев; длина шипа обычно равна её толщине.",
