"„+“ = Werkzeug wird neu angelegt. Schnittdaten sind Richtwerte für Hartmetall ({0}){1}; Kühlung: {2}.":"«+» = инструмент будет создан. Режимы резания – ориентировочные значения для твёрдого сплава ({0}){1}; охлаждение: {2}.",
"„Ineinander schachteln“ legt die Zuschnitte in die Lücken und Buchten ihrer Nachbarn und in deren Ausschnitte (ohne 90°-Drehen nur um 180° gewendet); der Abstand wird nie unterschritten. Ohne den Haken liegen sie nach ihrem umschließenden Rechteck in Reihen. Mit „Skizze + Körper“ entstehen flache Körper in Blechdicke, die sich in der Fertigung mit 2D-Kontur ausschneiden lassen.":"«Вложить друг в друга» укладывает заготовки в промежутки и выемки соседних деталей и в их вырезы (без поворота на 90°, только с переворотом на 180°); заданный зазор никогда не нарушается. Без флажка заготовки укладываются рядами по своим габаритным прямоугольникам. При выборе «Эскиз + тела» создаются плоские тела толщиной с лист, которые в производстве можно вырезать по 2D-контуру.",
"„Innen/Außen“ braucht geschlossene Konturen – offene Kurven mit „Auf der Kurve“ fräsen":"Для «Внутри/Снаружи» нужны замкнутые контуры – открытые кривые фрезеровать с «По кривой»",
"„Prüfen“ fährt den Ablauf in kleinen Zeitschritten ab und meldet, wann welche Körper zusammenstoßen.":"«Проверить» проходит последовательность малыми шагами по времени и сообщает, когда и какие тела сталкиваются.",
"„Skizze fertig“ → Extrusion, Rotation oder Bohrung.":"«Завершить эскиз» → Выдавливание, Вращение или Отверстие.",
"„Skizze“ → Ebene XY/XZ/YZ wählen oder eine ebene Fläche anklicken.":"«Эскиз» → выбрать плоскость XY/XZ/YZ или щёлкнуть плоскую грань.",
