"⚠ Das Programm ist nicht für Heidenhain geschrieben (Postprozessor wählen).":"⚠ Программа написана не для Heidenhain (выберите постпроцессор).",
"⚠ Fehler":"⚠ Ошибка",
"⚠ Jedes NC-Programm vor dem ersten Lauf prüfen: an der Maschine im Probelauf (Einzelsatz, reduzierter Eilgang) oder in einem externen NC-Simulator. Die Simulation hier ersetzt das nicht – Nutzung auf eigene Gefahr, ohne Gewährleistung.":"⚠ Проверяйте каждую управляющую программу перед первым запуском: на станке в пробном прогоне (покадровый режим, сниженная скорость ускоренных перемещений) или во внешнем симуляторе УП. Симуляция здесь этого не заменяет – использование на свой риск, без каких-либо гарантий.",
