"⚠ Lesen fehlgeschlagen:":"⚠ Не удалось прочитать:",
"⚠ Nach der letzten Änderung des Körpers war nicht eindeutig, welche Kante oder Fläche gemeint ist. Bitte prüfen – bei Bedarf löschen und neu projizieren.":"⚠ После последнего изменения тела стало неясно, какое ребро или какая грань имеется в виду. Проверьте – при необходимости удалите и спроецируйте заново.",
"⚠ Programmlogik (JavaScript) wird nicht ausgeführt: Sonderfunktionen, 4./5. Achse, Messzyklen und Maschinenoptionen bitte im Postprozessor-Editor prüfen.":"⚠ Логика программы (JavaScript) не выполняется: специальные функции, 4-ю/5-ю ось, измерительные циклы и опции станка проверьте в редакторе постпроцессора.",
